export function SplitPane({
  leftLabel = "{{leftLabel}}",
  rightLabel = "{{rightLabel}}",
  split = {{split}},
  orientation = "{{orientation}}",
  accent = "{{accent}}",
}) {
  const vertical = orientation === "vertical";
  return (
    <div style={{ display: "flex", flexDirection: vertical ? "row" : "column", height: 140, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430", border: "1px solid #24143022" }}>
      <div style={{ boxSizing: "border-box", flexShrink: 0, flexBasis: `${split}%`, overflow: "hidden", display: "flex", alignItems: "center", justifyContent: "center", background: "#fff" }}>{leftLabel}</div>
      <div style={{ flex: "none", position: "relative", background: accent, width: vertical ? 4 : "auto", height: vertical ? "auto" : 4, cursor: vertical ? "col-resize" : "row-resize" }} />
      <div style={{ boxSizing: "border-box", flexShrink: 0, flexBasis: `calc(100% - ${split}%)`, overflow: "hidden", display: "flex", alignItems: "center", justifyContent: "center", background: "#FAF7F2" }}>{rightLabel}</div>
    </div>
  );
}
